-- ── dj_music ──────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.partner_dj_music_profiles (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  service_id  UUID REFERENCES public.vendor_services(id) ON DELETE CASCADE,
  trade_id    TEXT NOT NULL DEFAULT 'dj_music' CHECK (trade_id = 'dj_music'),
  schema_version INTEGER NOT NULL DEFAULT 1,
  performance_kinds            TEXT[],
  event_types                  TEXT[],
  styles                       TEXT[],
  performers                   NUMERIC,
  own_equipment                TEXT,
  formats                      TEXT[],
  duration_options             TEXT[],
  setup_minutes                NUMERIC,
  equipment_included           TEXT,
  power_needs                  TEXT,
  space_needs                  TEXT,
  song_requests                BOOLEAN,
  special_production           TEXT,
  source_specs JSONB,
  backfilled_at  TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_dj_music_profile_service
  ON public.partner_dj_music_profiles (service_id) WHERE service_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_dj_music_profile_vendor ON public.partner_dj_music_profiles (vendor_id);

COMMENT ON COLUMN public.partner_dj_music_profiles.performance_kinds IS
  'What kind of music performances do you provide? [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.event_types IS
  'Which event types do you support? [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.styles IS
  'Which music styles do you play? [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.performers IS
  'How many performers can you provide? [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.own_equipment IS
  'Do you supply your own sound and lighting equipment? [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.formats IS
  'Performance format [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.duration_options IS
  'Duration options [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.setup_minutes IS
  'Setup / soundcheck time [required]';
COMMENT ON COLUMN public.partner_dj_music_profiles.equipment_included IS
  'Equipment included';
COMMENT ON COLUMN public.partner_dj_music_profiles.power_needs IS
  'Power requirements';
COMMENT ON COLUMN public.partner_dj_music_profiles.space_needs IS
  'Space / stage requirements';
COMMENT ON COLUMN public.partner_dj_music_profiles.song_requests IS
  'Takes playlist / custom song requests';
COMMENT ON COLUMN public.partner_dj_music_profiles.special_production IS
  'Special production requirements';

ALTER TABLE public.partner_dj_music_profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS partner_dj_music_profiles_owner ON public.partner_dj_music_profiles;
CREATE POLICY partner_dj_music_profiles_owner ON public.partner_dj_music_profiles FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_dj_music_profiles.vendor_id AND v.profile_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_dj_music_profiles.vendor_id AND v.profile_id = auth.uid()));

DROP POLICY IF EXISTS partner_dj_music_profiles_operator ON public.partner_dj_music_profiles;
CREATE POLICY partner_dj_music_profiles_operator ON public.partner_dj_music_profiles FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

COMMIT;

