SELECT table_name, (SELECT count(*) FROM information_schema.columns c
         WHERE c.table_schema = 'public' AND c.table_name = t.table_name) AS columns
  FROM information_schema.tables t
 WHERE table_schema = 'public' AND table_name IN ('partner_bar_beverages_profiles', 'partner_bar_beverages_items', 'partner_bridal_makeup_hair_profiles', 'partner_bridal_makeup_hair_items', 'partner_cake_desserts_profiles', 'partner_cake_desserts_items', 'partner_catering_food_profiles', 'partner_decoration_floral_profiles', 'partner_decoration_floral_items', 'partner_dj_music_profiles')
 ORDER BY table_name;
